#pragma once//#include <TrendStr.h>#include <PipeTransport.h>#include <TcpTransport.h>#undef CLIENTDLL_API#ifdef QUEUEAPM_EXPORTS#define CLIENTDLL_API Q_DECL_EXPORT        #else#define CLIENTDLL_API Q_DECL_IMPORT        #endif//#include "UniBuffer.h"struct CLIENTDLL_API SUniPoint : public SUniBuffer  {  SUniPoint() : SUniBuffer(sizeof(POINT)) {};  LPPOINT PT() { return (LPPOINT)m_szBuffer; }  };//struct STrendPaint  {  int n;// Номер в тренде  // Заполняется перед отображением  COLORREF color;  // Шкала в инженерных единицах.  // Заполняется перед отображением  double dMinEng,dMaxEng;  // Заполняется при отображении тренда  double dVarLineH,dVarLineC;//Метки  //  double MaxEng()    {    return dMaxEng;    }  double MinEng()    {    return dMinEng;    }  };//class CLIENTDLL_API CPipeTrends{  // Получение данных от модели  char* m_pFrom;  DWORD m_nSizeFrom;  //  SToTrend mTot;  SUniPoint mPT;  //  bool TrendPipe(SToTrend& to);  KPipeTransport m_pipeTransport;  KTcpTransport  m_tcpTransport;  INetworkTransport* m_pTransport;public:  CPipeTrends( bool bOverLapped = false );  virtual ~CPipeTrends(void);  //  virtual bool OutTrend( HDC hDC, STrendPaint* item, RECT rc, int nLineH, int nLineC, bool bBold, int nAddWidth = 0 );  //  bool OpenPipe();  bool ClosePipe();  //  bool TrendPipe( __time64_t nLast, int nTime );  bool TrendPipeS( __time64_t nLast, int nTime );//не проверяет на повторность по времени запроса данных   bool TrendPipe(SToTrend* to, char* from,DWORD dwSize);  bool TrendPipeMisha( __time64_t nLast, int nTime );  //  SUniPoint& PT()    {    return mPT;    }  //  SToTrend& Tot()    {    return mTot;    }  //  SFromTrend* From()    {    return (SFromTrend*)m_pFrom;    }  //  _Sxy* Data(int n)    {    SFromTrend* trend = From();    return trend->data+(mTot.nPoint+1)*2*n;    }  //  int  GetPoint()   {    return mTot.nPoint;   }  void SetPoint( int nPoint );  void ClearToT();  //  int Count()    {    return mTot.nCount;    }  //  int Add(const char* pszName,const char* pszParm)  {    strcpy_s( mTot.szName[mTot.nCount], pszName );    strcat_s( mTot.szName[mTot.nCount], "."     );    strcat_s( mTot.szName[mTot.nCount], pszParm );    mTot.nCount++;    return mTot.nCount-1;  }  //  int  Add(const char* pszName)  {    if( mTot.nCount>=_countof(mTot.szName) || !pszName )      return -1;    strcpy_s( mTot.szName[mTot.nCount], pszName );    mTot.nCount++;    return mTot.nCount-1;  }};